    {"id": "diani-modern-market", "cat": "market", "tier": "plenty", "priority": 63, "name": "Diani Modern Market (Mvindeni)", "short": "Mvindeni market", "neighborhood": "Ukunda / Mvindeni", "maps": "https://www.google.com/maps/search/?api=1&query=Diani+Modern+Market+Mvindeni+Ukunda", "badge": "", "tags": ["Market prices, cash/M-Pesa", "Walk-in", "Morning of a market day"], "productTags": ["Opened 2026"], "hours": "Daily; busiest on market days", "why": "For years Ukunda's traders sold in the open, in dust and rain, with goods stolen overnight. The covered market at Mvindeni replaced that: more than two hundred stalls, eateries, cold storage for perishables, borehole water and floodlights. President Ruto opened it on 23 May 2026. By August the traders were saying business was picking up and asking for credit to grow, while some sellers still worked the roadside outside the gates.", "address": "", "phone": "", "status": "confirmed", "statusChecked": "2026-10-11", "lat": -4.316, "lng": 39.547, "hook": "Ukunda's covered market at Mvindeni, opened by the President in May 2026, with cold rooms behind the veg rows.", "signature": "The mama mboga rows with actual cold storage behind them", "verdict": "The new centre of gravity for produce — go the morning of a market day and watch a town upgrade itself.", "caveat": "Three months old at research: the cooked-food court is still settling; coordinates are locality-level.", "best_time": "Morning of a market day", "buy": "Tomatoes, onions, greens, fruit — the wholesale-ish end of Diani's chain; coconuts in every grade; cassava.", "galley": "Upcountry vegetables are trucked in — what is genuinely local is the coconut ladder, cassava, greens, citrus and the mango flood in season.", "category": "landings", "subcat": "WHERE THE BOATS LAND", "dishes": [{"name": "Produce under cover", "note": "219 stalls, cold storage, commissioned 23 May 2026 — the old open-air market's replacement"}, {"name": "Cold-chain perishables", "note": "the thing the old Ukunda market never had"}, {"name": "The food court", "note": "cash or M-Pesa; morning of a market day"}], "hot_this_month": "The first mangoes of the season arrive in November; the main crop runs December to March."},
    {"id": "moiz-swahili", "cat": "shop", "tier": "plenty", "priority": 14, "name": "Moiz Swahili Dishes", "short": "Moiz", "neighborhood": "Ukunda (Hospital Road)", "maps": "https://www.google.com/maps/search/?api=1&query=Moiz+Swahili+Dishes+Ukunda", "badge": "SWAHILI", "tags": ["Biryani KES 715 (Glovo, obs. 2026-08)", "Walk-in or Glovo", "Lunch, early"], "productTags": ["Biryani"], "hours": "Lunch-centred; Tripadvisor lists closing at 19:30 (undated) - call ahead", "why": "Moiz is a working lunch room rather than a place to linger. Coast-style biryani is the reason to come, served with a sharp chicken mchuzi spooned over the rice, alongside pilau and vegetable samosas made that day. Listings place it variously on Hospital Road, Diani Palm Road and in the Diani Legend Store building, all in the streets behind the beach road. Its live delivery listing is the best day-to-day sign that the kitchen is cooking.", "address": "", "phone": "+254 729 981 087", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.2776, "lng": 39.5866, "category": "swahili", "subcat": "THE SWAHILI KITCHENS", "hook": "A small Ukunda canteen cooking coast biryani with tangy chicken mchuzi and samosas fried fresh.", "signature": "Chicken biryani with the mchuzi over", "verdict": "Go early: biryani freshness decides the meal.", "caveat": "Consistency reports vary day to day — an early plate is the honest one.", "price_range": "KES 200–1,400 (Glovo, obs. 2026-08)", "reservation": "Walk-in; Glovo", "best_time": "Lunch, early", "dishes": [{"name": "Chicken biryani", "note": "KES 715 on Glovo (obs. 2026-08); cheaper at the counter"}, {"name": "Vegetable samosas", "note": "made fresh — the reliable snack"}, {"name": "Mishkaki plate", "note": "KES 465 (obs. 2026-08)"}]},
    {"id": "karafuu", "cat": "shop", "tier": "plenty", "priority": 15, "name": "Karafuu Restaurant", "short": "Karafuu", "neighborhood": "Ukunda town", "maps": "https://www.google.com/maps/search/?api=1&query=Karafuu+Restaurant+Ukunda", "badge": "GRILL", "tags": ["Mains KES 120–1,430 (obs. 2026-08)", "Walk-in; Glovo delivers", "Evening choma"], "productTags": ["Nyama choma"], "hours": "From 07:00 (Glovo); evening for choma off the grill", "why": "Karafuu means clove in Swahili, and this is a town kitchen, opposite Equity Bank in Ukunda rather than on the beach strip. The fire handles chicken and mutton choma and whole fish, and the pot handles pweza, an octopus soup sold for KES 300 in August 2026. Pilau and chips masala round it out, and its own page also offers seafood pizza. A second branch, Golden Karafuu, sits at the north end of the beach road, and Glovo delivers across Diani.", "address": "", "phone": "+254 702 349 629", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.2822, "lng": 39.5676, "category": "swahili", "subcat": "THE SWAHILI KITCHENS", "hook": "Ukunda's town grill opposite Equity Bank: charcoal chicken, whole fish and octopus soup, far from the beach.", "signature": "Pweza soup — octopus, KES 300 (obs. 2026-08)", "verdict": "Town cooking at town prices; the choma justifies the drive inland.", "caveat": "Glovo prices quoted — expect slightly less at the counter. No view, no breeze: that is the point.", "price_range": "KES 120–1,430 (Glovo, obs. 2026-08)", "reservation": "Walk-in; Glovo", "best_time": "Evening, choma off the grill", "best_night": "Any", "dishes": [{"name": "Pweza soup", "note": "octopus soup, a coast staple rarely on tourist menus — KES 300 (obs. 2026-08)"}, {"name": "Kuku choma", "note": "the local benchmark grilled chicken — KES 355"}, {"name": "Mchicha wa nazi", "note": "greens in coconut — KES 120"}, {"name": "Fish choma", "note": "whole grilled fish — KES 950"}]},
    {"id": "swahili-pot", "cat": "shop", "tier": "plenty", "priority": 13, "name": "Swahili Pot", "short": "Swahili Pot", "neighborhood": "Ukunda (toward the beach road)", "maps": "https://www.google.com/maps/search/?api=1&query=Swahili+Pot+Ukunda", "badge": "SWAHILI", "tags": ["Mains ~KES 650 (obs. 2026-08)", "Walk-in or Glovo", "Lunch"], "productTags": ["Makuti", "African Pot"], "hours": "Daytime into evening (Glovo listing live; confirm midday)", "why": "Swahili Pot is a garden canteen under a makuti roof on the road between Ukunda town and Diani, and belongs to the same family as the long-running African Pot in Ukunda. The cooking is coastal home food: pilau first, then biryani, fried and grilled fish, and ukwaju, the sour tamarind juice. Most residents order it through Glovo on weeknights, and that live delivery listing is also how its trading is checked.", "address": "", "phone": "", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.284738, "lng": 39.573132, "category": "swahili", "subcat": "THE SWAHILI KITCHENS", "hook": "A makuti-roofed canteen between Ukunda and the beach road: pilau, biryani and fish for the neighbourhood.", "signature": "Pilau — the calling card", "verdict": "Honest canteen cooking; order what the day cooked, not what the menu promises.", "caveat": "Quality varies more than at the breakfast benchmarks — this is a canteen, not a kitchen with a chef's name on it.", "price_range": "Mains ~KES 650, breakfast KES 40–250 (Glovo, obs. 2026-08)", "reservation": "Walk-in; Glovo delivers", "best_time": "Lunch, before popular dishes run out", "dishes": [{"name": "Pilau", "note": "spiced rice with meat — the order"}, {"name": "Coast biryani", "note": "with the mchuzi poured over the rice"}, {"name": "Grilled fish", "note": "whole, from the day's landing"}]},
    {"id": "leonardos", "cat": "shop", "tier": "plenty", "priority": 9, "name": "Leonardo's (Leonardo il Ristorante)", "short": "Leonardo's", "neighborhood": "Diani north", "maps": "https://www.google.com/maps/search/?api=1&query=Leonardo%27s+Restaurant+Diani+Beach", "badge": "ITALIAN", "tags": ["$$$ band", "Book dinner in season", "Garden dinner; gelato any afternoon"], "productTags": ["Wood oven", "Since ~2004"], "hours": "Daily 08:00-23:00; kitchen to 22:30, last food orders 22:15 (own site, undated; Tripadvisor says to 23:30 - call ahead for a late table)", "why": "Mario Scianna, from Sicily, opened Leonardo's on the Diani strip more than twenty years ago, and his son Roberto has run it since around 2019. The pizza is Roman-style, slow-risen and baked in a wood oven; pasta is made by hand. The family says theirs was the first true Italian gelato made in Diani, using methods from Mario's home town. In March 2024 Jackson Biko of Business Daily compared the lit makuti dining room at night to an ocean liner.", "address": "Diani Beach Road (Colliers Centre stretch)", "phone": "+254 720 501 707", "status": "confirmed", "statusChecked": "2026-10-11", "lat": -4.2877255, "lng": 39.5869355, "category": "italian", "subcat": "THE ITALIAN RESIDENCY", "hook": "A Sicilian family's wood-oven Italian on the beach road, with handmade pasta and gelato to their own recipe.", "person": "Mario Scianna (founder); son Roberto at the helm since ~2019", "signature": "Linguine Indian Ocean — handmade pasta, local seafood", "verdict": "The reliable Italian dinner of the strip, and the correct afternoon gelato stop.", "caveat": "Roadside garden, not on the sand — go for the food, not a view.", "price_range": "$$$ (EatOut banding)", "reservation": "Book for dinner in season; walk-in lunch", "best_time": "Dinner in the garden; gelato mid-afternoon", "dishes": [{"name": "Wood-fired Margherita", "note": "San Marzano, fior di latte — the benchmark of the crust"}, {"name": "Linguine Indian Ocean", "note": "handmade pasta with the local catch"}, {"name": "Gelato", "note": "the claimed first true Italian gelato in Diani — the family's claim, and a good one"}, {"name": "Tiramisu della casa", "note": "espresso-soaked, made in-house"}], "web": "https://leonardosdiani.com", "charter": {"price": "$$$ — mid-Italian", "book": "Phone 0720 501707 · book dinner in season, walk-in lunch", "dress": "Casual", "warn": "Roadside garden — no ocean view", "fit": "The easy win: wood-fired Roman crust and the family gelato, walking distance from the north hotels."}},
    {"id": "aniellos", "cat": "shop", "tier": "plenty", "priority": 10, "name": "Aniello's Ristorante Pizzeria", "short": "Aniello's", "neighborhood": "Diani north", "maps": "https://www.google.com/maps/search/?api=1&query=Aniello%27s+Diani+Beach", "badge": "ITALIAN", "tags": ["Mid-range", "Walk-in", "Dinner"], "productTags": ["Wood oven"], "hours": "Reported 10:00–22:00 daily — undated; call before crossing town", "why": "Aniello, an Italian who settled on the south coast decades ago, has run this pizzeria as a family business for most of the strip's modern history. The oven is wood-fired and the menu leans Neapolitan, with simple fish plates alongside; the French guide Petit Fute counted some fifty pizzas on the list. Residents, the Ocean Tribe dive crew among them, keep naming it as their local Italian. Diners were still reviewing it in March 2026, though it publishes no website or hours.", "address": "", "phone": "", "status": "confirmed", "statusChecked": "2026-10-11", "lat": -4.288738, "lng": 39.586456, "category": "italian", "subcat": "THE ITALIAN RESIDENCY", "hook": "Aniello's long-running pizzeria near Leonardo's, with a wood oven and a pizza list that runs to about fifty.", "person": "Aniello (Italian owner, decades on the coast)", "signature": "Wood-fired pizza, Neapolitan-leaning", "verdict": "The local's Italian — checked by reputation, not by paperwork.", "caveat": "No own website or published hours; a basic roadside trattoria, not a beach room - phone or drive by before a special trip.", "price_range": "Mid-range (undated)", "reservation": "Walk-in", "best_time": "Dinner", "dishes": [{"name": "Wood-fired pizza", "note": "the local Italians' order"}, {"name": "Fish of the day", "note": "simply done, Italian-style"}]},
    {"id": "kokkos", "cat": "shop", "tier": "plenty", "priority": 33, "name": "Kokkos Cafe Bistro", "short": "Kokkos", "neighborhood": "Diani central", "maps": "https://www.google.com/maps/search/?api=1&query=Kokkos+Cafe+Diani", "badge": "", "tags": ["$$ band", "Walk-in", "Weekday lunch; breakfast"], "productTags": ["Since 2000"], "hours": "Breakfast to late evening; own site says Mon-Sat 08:00-23:00, Sun 09:00-16:30, Tripadvisor says about 07:30-22:30, to 23:30 Fri-Sat - call ahead, especially Sunday", "why": "Kokkos opened in 2000, when the Diani strip had almost no serious coffee, and for years it was the one place to get it. The house drink is the kokkoccino, a flavoured cappuccino named after the café. The kitchen plates bistro food with local, Asian and European threads, and on weekdays the tables fill at lunch with residents, NGO staff and hotel managers. Reviews kept coming through 2026, but its posted hours differ between listings.", "address": "", "phone": "+254 721 565 567", "status": "confirmed", "statusChecked": "2026-10-11", "lat": -4.307477, "lng": 39.578119, "hook": "Diani's café of record since 2000: espresso, the house kokkoccino and bistro plates for the weekday crowd.", "signature": "Kokkoccino — the drink they named after themselves", "verdict": "The dependable middle of Diani's café life; order breakfast and watch the strip go to work.", "caveat": "Own-site copyright reads 2020 — confirm the early Sunday close before relying on it.", "best_time": "Weekday lunch; breakfast", "dishes": [{"name": "Kokkoccino", "note": "the house flavoured cappuccino"}, {"name": "Eggs benedict", "note": "the expat breakfast order"}], "category": "breakfast", "subcat": "THE BREAKFAST TABLES", "web": "https://kokkoscafe.com"},
    {"id": "pallet-cafe-diani", "cat": "shop", "tier": "plenty", "priority": 26, "name": "Pallet Cafe Diani Beach", "short": "Pallet Cafe", "neighborhood": "Galu / Kinondo", "maps": "https://www.google.com/maps/search/?api=1&query=Pallet+Cafe+Diani+Galu", "badge": "CAFE", "tags": ["Coworking day pass KES 1,200 (obs. 2026-08)", "Walk-in; WhatsApp for desks", "Weekday morning; Sunday live music"], "productTags": ["Deaf-staffed", "Est. 2019"], "hours": "Reported 09:00–16:00 at the beach site — confirm on Instagram", "why": "Feisal Hussein founded Pallet in Nairobi in 2019 to train and employ deaf and hard-of-hearing waiters. That first café closed on 15 April 2026 to make room for a petrol station, which left the Galu beach branch, open since 2023, as the brand's centre. There are no walls: hammocks, beach beds and makuti umbrellas, plus a corner for laptops that doubles as a space for local art. Business Daily profiled Safari, a deaf staffer trained in-house on coffee and cocktails.", "address": "", "phone": "", "status": "confirmed", "statusChecked": "2026-10-11", "lat": -4.3731018, "lng": 39.5558721, "category": "breakfast", "subcat": "THE FAST PLATE", "hook": "A deaf-staffed café on Galu sand where you order coffee using the sign language printed on the menu.", "person": "Feisal Hussein (founder, 2019)", "signature": "Barista coffee by deaf-trained staff — the founding idea in a cup", "verdict": "The strip's warmest room, and the honest beach coworking answer if the 4G cooperates.", "caveat": "Open-air on sand: glare, salt breeze, patchy signal. Coworking prices are the brand's central plan — confirm locally.", "price_range": "Mid; coworking day pass KES 1,200 (obs. 2026-08)", "reservation": "Walk-in; WhatsApp for the desk corner", "best_time": "Weekday morning; Sunday brings live music and crowds", "dishes": [{"name": "Barista coffee", "note": "the founding trade, signed across the counter"}, {"name": "Burgers", "note": "singled out as excellent in the Business Daily profile"}, {"name": "Zoodles", "note": "the house signature per its own menu"}]},
    {"id": "diani-bakehouse", "cat": "shop", "tier": "plenty", "priority": 37, "name": "Diani Bakehouse", "short": "Bakehouse", "neighborhood": "Diani central (beside Apero)", "maps": "https://www.google.com/maps/search/?api=1&query=Diani+Bakehouse+Diani+Beach+Road", "badge": "", "tags": ["Cakes to order", "Walk-in", "Morning, while the bake is fresh"], "productTags": [], "hours": "Unpublished — check @diani_bakehouse before crossing town", "why": "Diani Bakehouse is locally owned and bakes bread that is hard to find on this coast: German seed loaves, challah, croissants, cinnamon rolls and Berliners filled with fruit preserves, with cakes and cupcakes to order. The German loaves are a trace of the European residents who built many of the strip's first hotels. Its own web page is a bare listing that places it next to Apero Bar and Restaurant, and it posts no opening hours at all.", "address": "", "phone": "", "status": "unverified", "statusChecked": "2026-08-20", "lat": -4.3074731, "lng": 39.5776242, "hook": "A small artisan bakery beside Apero, baking German seed breads, challah and jam-filled Berliners.", "verdict": "Pair it with Kokkos next door; go early for the proper loaf.", "caveat": "Thinnest paper trail in the café lane — hours unpublished, liveness unproven.", "best_time": "Morning", "category": "breakfast", "subcat": "THE BREAKFAST TABLES", "dishes": [{"name": "German seed loaves", "note": "a living trace of the expat community that built this strip's first hotels"}, {"name": "Berliners and cinnamon rolls", "note": "jam-filled; go while the bake is fresh"}, {"name": "Challah and croissants", "note": "cakes to order"}], "web": "https://sites.google.com/view/dianibakehouse254/home"},
    {"id": "mwaepe-fishermen", "cat": "market", "tier": "plenty", "priority": 21, "name": "Mwaepe Fishermen Beach Restaurant", "short": "Mwaepe Fishermen", "neighborhood": "Galu (Mwaepe village)", "maps": "https://www.google.com/maps/search/?api=1&query=Mwaepe+fish+landing+Diani", "badge": "FISH", "tags": ["Budget", "Walk-in", "Ask what came in"], "productTags": ["BMU village"], "hours": "Unverified — daylight, tide-led", "why": "This is the restaurant of the fishermen's village at Mwaepe, a few steps from Colobus Shade, and about as close as Diani gets to eating inside its fishery. Fish, prawns and calamari are fried or grilled to order above the beach where the ngalawa outrigger canoes come in. The village's Beach Management Unit took this land back from grabbers and holds its title, and a state-backed upgrade of the landing site began here in 2025.", "address": "", "phone": "+254 713 525 196", "status": "unverified", "statusChecked": "2026-08-20", "lat": -4.34323, "lng": 39.566465, "category": "grills", "subcat": "THE FIRE", "hook": "The Mwaepe fishing community's own family-run kitchen, frying the day's catch beside the landing beach.", "signature": "Fried whole fish, straight off the boats", "verdict": "Eat where the fishery eats; ask what came in, not what you fancy.", "caveat": "Basic conditions; liveness rests on the village, not a website — expect construction works from the 2025 upgrade.", "price_range": "Budget (no dated prices)", "reservation": "Walk-in", "best_time": "Lunch after the landing", "dishes": [{"name": "Fried whole fish", "note": "snapper or the day's catch"}, {"name": "Prawns and calamari", "note": "simple, cheap, to order"}]},
    {"id": "colobus-shade", "cat": "market", "tier": "plenty", "priority": 20, "name": "Colobus Shade", "short": "Colobus Shade", "neighborhood": "Galu (Mwaepe landing)", "maps": "https://www.google.com/maps/search/?api=1&query=Colobus+Shade+Mwaepe+Galu+Diani", "badge": "FISH", "tags": ["KES 500–1,800/head (2023–24 reports)", "Walk-in; call ahead for lobster", "Lunch after the boats land"], "productTags": ["Charcoal", "No alcohol"], "hours": "Reported 09:00–21:00 (undated) — call first", "why": "Colobus Shade stands at Mwaepe, where Diani's reef fishermen land, and the charcoal grill works metres from where the boats come in. The order is the seafood platter of lobster, crab, prawns and fish, priced well below the beach-road restaurants: travellers reported a whole lobster at about KES 1,500 to 1,800 in 2023 and 2024. The owners are Muslim and serve no alcohol, so drink madafu instead. Residents and the Ocean Tribe dive shop send people here.", "address": "", "phone": "+254 724 634 839", "status": "unverified", "statusChecked": "2026-08-20", "lat": -4.342994, "lng": 39.565722, "category": "grills", "subcat": "THE FIRE", "hook": "A sand-floored seafood kitchen at the Mwaepe landing, grilling lobster, crab and fish over charcoal.", "signature": "The landing-site seafood platter", "verdict": "The most honest seafood transaction on the strip: fish, fire, sand, done.", "caveat": "Rustic in every sense — flies at midday, freshness rides on the day's landing; call before a special trip.", "price_range": "KES 500–1,800/head (2023–24 reports, unverified)", "reservation": "Walk-in; lobster by phone", "best_time": "Lunch, after the morning boats", "dishes": [{"name": "Seafood platter", "note": "lobster, crab, prawns, calamari — the order everyone comes for"}, {"name": "Charcoal-grilled snapper", "note": "whole fish, landed on this beach"}]},
    {"id": "ukunda-junction-vendors", "cat": "market", "tier": "plenty", "priority": 72, "name": "Ukunda junction evening grills", "short": "The junction", "neighborhood": "Ukunda (Beach Road × Likoni–Lunga Lunga)", "maps": "https://www.google.com/maps/search/?api=1&query=Ukunda+junction+Diani", "badge": "", "tags": ["KES 20 corn to low hundreds (obs. 2026-05)", "Walk up, point, pay cash/M-Pesa", "Just after sunset"], "productTags": [], "hours": "~16:00 until late; busiest after dark", "why": "The junction of the Diani beach road and the Likoni-Lunga Lunga highway is Ukunda's transport centre, and from late afternoon it turns into an open-air kitchen. Potatoes are dipped in turmeric batter and fried in karai pans as viazi karai, served with chilli and tamarind; mishkaki skewers go over the coals, and roast maize sells for about KES 20. The vendors have no names and change from night to night, so follow the queue of boda riders to the freshest oil.", "address": "", "phone": "", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.281409, "lng": 39.566161, "hook": "Where Ukunda's matatu and boda crews eat after dark: viazi karai, mishkaki and roast maize at the crossroads.", "signature": "Viazi karai off the karai, ukwaju sauce over", "verdict": "Twenty minutes and small money for the town's true evening flavour.", "caveat": "A dark, busy junction at night — go early evening, phones pocketed.", "best_time": "Just after sunset, grills at full heat", "category": "grills", "subcat": "THE FIRE", "dishes": [{"name": "Viazi karai", "note": "potato in turmeric batter with chilli-tamarind, straight out of the karai"}, {"name": "Mishkaki", "note": "marinated skewers over the coals"}, {"name": "Grilled corn", "note": "about KES 20 (obs. 2026-05)"}]},
    {"id": "havana-diani", "cat": "shop", "tier": "plenty", "priority": 19, "name": "Havana Bar & Restaurant", "short": "Havana", "neighborhood": "Diani central", "maps": "https://www.google.com/maps/search/?api=1&query=Havana+Bar+Diani+Beach+Road", "badge": "BAR-FOOD", "tags": ["KES 70–4,000 menu (obs. 2026-08)", "Walk-in; M-Pesa till 899654", "Post-23:00 kitchen"], "productTags": ["Open late"], "hours": "Daily until 01:00 (opening hour unpublished)", "why": "Havana opened as the coast outpost of a long-running Nairobi bar, and its use is simple: the kitchen stays on until 01:00 every night. The menu runs from KES 70 mint water to a KES 4,000 seafood grill (August 2026), with pizzas, grilled calamari and Cuban-leaning plates in between. It sits by the road rather than on the beach, takes M-Pesa and delivers through Glovo, so it is where a crew finishing a late service can still eat.", "address": "", "phone": "+254 724 803 452", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.308, "lng": 39.5682, "category": "chefs-eat", "subcat": "WHERE THE RESIDENTS EAT", "hook": "The Diani branch of Nairobi's Havana Bar, cooking from morning until 01:00 every day of the week.", "signature": "Grilled calamari — the house order", "verdict": "Not a destination; a lifeline. Every strip needs one and this is Diani's.", "caveat": "Roadside, not beachfront; its own website is stale (© 2023) — the live Glovo listing is the real-time signal.", "price_range": "KES 70–4,000 (obs. 2026-08)", "reservation": "Walk-in", "best_time": "Late evening — one of the few reliable post-23:00 kitchens", "best_night": "Any", "dishes": [{"name": "Grilled calamari", "note": "the house signature"}, {"name": "Mixed seafood grill for two", "note": "KES 4,000, the top of the menu (obs. 2026-08)"}], "charter": {"price": "KES 70–4,000 (obs. 2026-08)", "book": "Walk-in", "dress": "", "warn": "Roadside, not beachfront; its own website is stale (© 2023) — the live Glovo listing is the real-time signal.", "fit": "The Diani branch of Nairobi's Havana Bar, cooking from morning until 01:00 every day of the week."}},
    {"id": "funky-monkey", "cat": "shop", "tier": "plenty", "priority": 27, "name": "Funky Monkey Cocktail Bar", "short": "Funky Monkey", "neighborhood": "Diani central", "maps": "https://www.google.com/maps/search/?api=1&query=Funky+Monkey+Diani+Beach", "badge": "", "tags": ["Cocktails", "WhatsApp for salsa night", "Wednesday salsa"], "productTags": ["50 Best"], "hours": "Sun–Tue 07:30–23:00, Wed–Sat 07:30–24:00 (kitchen to 21:30)", "why": "The team behind the Salty Squid opened Funky Monkey in July 2022 in a roadside courtyard. It became the first bar on the Kenyan coast listed on 50 Best Discovery, and the Tales of the Cocktail Spirited Awards named it in the Middle East and Africa top ten for Best International Bar Team and Best International Restaurant Bar in 2024, 2025 and 2026. The drinks fold Kenyan ingredients into classics: a smoked Negroni, a pineapple and basil smash.", "address": "", "phone": "+254 742 794 527", "status": "confirmed", "statusChecked": "2026-10-11", "lat": -4.3064472, "lng": 39.5785532, "hook": "A courtyard cocktail bar opened in 2022 by the Salty Squid team, now a regular on regional award lists.", "signature": "Smoked Negroni", "verdict": "The best bar programme between Zanzibar and Nairobi, in a courtyard with no sea view at all.", "caveat": "Roadside courtyard, no ocean — the point is the bar team, not the postcard.", "best_time": "Wednesday salsa night; Wed–Sat runs to midnight", "best_night": "Wed", "dishes": [{"name": "Smoked Negroni", "note": "the house twist cited in its 50 Best Discovery profile"}, {"name": "Pineapple Basil Smash", "note": "the tropical-produce signature"}], "signal_chip": {"label": "50 BEST DISCOVERY", "full": "Listed on 50 Best Discovery (World's 50 Best platform); Tales of the Cocktail Spirited Awards MEA Top-10 honoree, Best International Bar Team & Best International Restaurant Bar, 2024, 2025 and 2026", "cosign": "talesofthecocktail.org, 2026-04-06"}, "category": "chefs-eat", "subcat": "THE FAST PLATE"},
    {"id": "the-41-beach-club", "cat": "shop", "tier": "plenty", "priority": 25, "name": "The 41 Beach Club", "short": "The 41", "neighborhood": "Diani central", "maps": "https://www.google.com/maps/search/?api=1&query=The+41+Beach+Club+Diani", "badge": "BEACH", "tags": ["Sunbed KES 1,500; dhow cruise KES 5,000 (obs. 2026-08)", "Walk-in weekdays; reserve weekends", "Late afternoon into sundowners"], "productTags": ["Solar", "Baobab bar"], "hours": "From 11:00 daily to 22:00, to 23:00 on weekend nights (own site says Sat-Sun, older listing Fri-Sat; Tripadvisor says 22:00 daily) - call ahead", "why": "When Forty Thieves, George Barbour's famous beach bar, closed after his death in 2018, Diani lost its meeting place. Claudia and Richard Glaser, who ran Nomad's beach bar for fourteen years, opened The 41 to fill that role, in what its own site calls the former Aga Khan Hall. The bar wraps an old baobab, the compound runs on solar, and there is a Koroga corner where you cook your own pot. Ocean Tribe's dive base works from the same site.", "address": "", "phone": "+254 758 423 283", "status": "confirmed", "statusChecked": "2026-10-11", "lat": -4.314, "lng": 39.5772, "category": "beach-rooms", "subcat": "THE BEACH ROOMS & THE CLUBS", "hook": "A beach bar in Diani's old Aga Khan Hall, built around a baobab by the pair who ran Nomad's bar.", "person": "Claudia & Richard Glaser (founders — 14 years running Nomad's beach bar)", "signature": "Koroga corner — cook-your-own Kenyan-Indian pots", "verdict": "The successor, not the resurrection — and on a Saturday afternoon, that is enough.", "caveat": "A beach club, not gastronomy; the Forty Thieves lineage is its own claim. Anyone promising guests the original is out of date.", "price_range": "Mid beach club; sunbed KES 1,500 (obs. 2026-08)", "reservation": "Walk-in weekdays; reserve weekends - +254 758 423 283 or reservations@the41beachclub.com", "best_time": "Saturday/Sunday afternoon into sundowner", "best_night": "Sat", "dishes": [{"name": "Koroga corner", "note": "cook-your-own curry pots — billed as Diani's first"}, {"name": "Local catch grills", "note": "beach-bar register, prices unpublished"}], "web": "https://the41beachclub.com"},
    {"id": "salty-squid", "cat": "shop", "tier": "plenty", "priority": 24, "name": "The Salty Squid Beach Bar & Restaurant", "short": "Salty Squid", "neighborhood": "Galu / Kinondo", "maps": "https://www.google.com/maps/search/?api=1&query=Salty+Squid+Beach+Bar+Galu+Diani", "badge": "BEACH", "tags": ["Mid-range beach bar", "Book ahead — often full", "Sunset at kite-o'clock"], "productTags": ["Kite scene"], "hours": "Daily 07:30–22:00; kitchen 12:00–20:30, breakfast 07:30–11:30", "why": "The Salty Squid sits on the sand inside the Kenyaways kite village at Galu, next to the H2O Extreme kite school, which makes it the dining room of Diani's wind scene. Seared local yellowfin, garlic king prawns, dorado and reef lobster lead the menu, and the bar claims the largest gin list on the Kenyan coast. Oli and Hal, who run it, also opened Funky Monkey. The kitchen stops early: last food orders 20:30, last drinks 21:30.", "address": "", "phone": "+254 758 515 609", "status": "confirmed", "statusChecked": "2026-10-11", "lat": -4.350437, "lng": 39.563732, "category": "beach-rooms", "subcat": "THE BEACH ROOMS & THE CLUBS", "hook": "The beach bar of the Kenyaways kite village at Galu, serving yellowfin and prawns as the kites come in.", "cosign": "Sister venue of Funky Monkey — the 50 Best Discovery bar team", "person": "Oli and Hal (operators)", "signature": "Seared yellowfin tuna, local catch", "verdict": "Book it in kite season and watch the sky traffic with dinner.", "caveat": "Last food orders 20:30, bar 21:30 — this is a sunset room, not a late one.", "price_range": "Mid-range beach bar", "reservation": "Book ahead — phone/WhatsApp; often fully booked", "best_time": "Sunset; kite seasons (mid-Dec–mid-Mar, Jun–mid-Sep) for the show", "best_night": "Any in season", "dishes": [{"name": "Seared yellowfin tuna", "note": "the most-cited plate"}, {"name": "Garlic king prawns", "note": "order with a sundowner"}, {"name": "Chilli mango margarita", "note": "the bar's signature at kite-o'clock"}], "web": "https://saltysquidbeachbar.com", "charter": {"price": "Mid beach bar", "book": "Phone/WhatsApp +254 758 515 609 · often fully booked · kitchen closes 20:30", "dress": "Barefoot", "warn": "Last food orders 20:30 — an early room", "fit": "The sunset table: yellowfin and king prawns while the kites land in front."}},
    {"id": "charlie-claws", "cat": "mainland", "tier": "plenty", "priority": 22, "name": "Charlie Claw's (Wasini Island Restaurant)", "short": "Charlie Claw's", "neighborhood": "Wasini Island", "maps": "https://www.google.com/maps/search/?api=1&query=Wasini+Island+Restaurant+Charlie+Claws", "badge": "CRAB", "tags": ["Package pricing — agree in writing", "Book ahead via wasini.com or hotels", "Oct–Mar seas"], "productTags": ["Since 1978", "Dugout crab"], "hours": "Day-trip lunch service; sunset cruises — no public timetable", "why": "Charlie Claw's says it has fed visitors on Wasini since 1978. Crab and fish come ashore by dugout canoe and are eaten in an open room under palm thatch above the channel, and it holds the only bar licence on this mostly Muslim island. Its own jahazi dhows sail to Kisite under a twelve-point dolphin code: approach parallel, stay twenty minutes at most, never swim with or feed them. Its community fund pays teachers on both sides of the channel.", "address": "", "phone": "+254 722 205 154", "status": "confirmed", "statusChecked": "2026-10-11", "lat": -4.6586, "lng": 39.36454, "category": "story", "subcat": "THE OLD HOUSES", "hook": "Wasini Island's original restaurant, serving dugout-landed crab since 1978 on the Kisite dhow day.", "signature": "The grilled crab — the specialty since 1978", "verdict": "Book the whole dhow day, not lunch alone — the crossing is the point.", "caveat": "No published prices: agree the package in writing before the day. Tour-group waves peak around 13:00.", "price_range": "Package on enquiry", "reservation": "Book ahead — wasini.com or through Diani hotels", "best_time": "Oct–Mar; as part of the full dhow day", "dishes": [{"name": "Grilled crab", "note": "bought daily off the fishermen's dugouts — the house speciality"}, {"name": "Swahili Blue set menu", "note": "the traditional alternative to the seafood feast"}], "web": "https://wasini.com"},
    {"id": "twiga-lodge", "cat": "mainland", "tier": "plenty", "priority": 23, "name": "Twiga Lodge & Campsite (Tiwi)", "short": "Twiga Lodge", "neighborhood": "Tiwi", "maps": "https://www.google.com/maps/search/?api=1&query=Twiga+Lodge+Tiwi+Beach", "badge": "SHACK", "tags": ["Budget; camping ~KES 400 (2025)", "Walk-in", "Weekend lunch off the reef walk"], "productTags": ["Campsite"], "hours": "Unverified — daytime kitchen at best", "why": "Tiwi, north of Diani, has almost no restaurants: villas cook for themselves and fishermen sell straight off the sand. Twiga Lodge, a budget beachfront lodge and campsite, is the exception, with a bar and kitchen under the palms serving simple plates and cold beer. Camping ran at around KES 400 a head in 2025 listings. Reef walks described in 2026 still begin and end here, but other recent reports are mixed, so arrive expecting drinks and be glad of food.", "address": "", "phone": "", "status": "unverified", "statusChecked": "2026-08-20", "lat": -4.240368, "lng": 39.602813, "category": "story", "subcat": "THE OLD HOUSES", "hook": "A budget lodge and campsite on Tiwi beach whose palm-shaded bar is the stretch's only public kitchen.", "signature": "Grilled fish and a cold Tusker after the reef walk", "verdict": "Go for Tiwi's emptiness; eat whatever the kitchen honestly has.", "caveat": "Mixed 2024–26 signals (one report of it 'seeming deserted'); the access road is best not driven after dark — long-standing local advice.", "price_range": "Budget; camping ~KES 400/person (2025 listings)", "reservation": "Walk-in", "best_time": "Lazy weekend lunch after the Kongo Mosque walk", "dishes": [{"name": "Grilled fish", "note": "simple and cheap — set expectations accordingly"}, {"name": "Cold beer under the palms", "note": "the actual order"}]},
    {"id": "madafu-vendors", "cat": "market", "tier": "plenty", "priority": 71, "name": "Madafu vendors (roaming)", "short": "The madafu men", "neighborhood": "Diani & Galu beaches", "maps": "https://www.google.com/maps/search/?api=1&query=Diani+Beach+madafu", "badge": "", "tags": ["KES 50–100 settled rate (obs. 2026)", "Flag one down; agree first", "Midday heat"], "productTags": [], "hours": "Daylight, wherever people are", "why": "No one owns this trade; it walks the beach. Vendors carry green drinking coconuts and open them to order with a panga, and the settled price in 2026 was KES 50 to 100, with higher opening bids outside the big hotels. Drink the water, hand the nut back and ask for kuna: the vendor splits the shell, cuts a scoop from the husk, and you eat the soft young flesh inside.", "address": "", "phone": "", "status": "confirmed", "statusChecked": "2026-04-03", "hook": "Roaming coconut sellers on Diani and Galu sand: green nuts opened by panga, then split for the jelly.", "signature": "Madafu with the kuna scoop — the shell-slice spoon is the point", "verdict": "The correct answer to Diani heat, four times a day.", "caveat": "Individually unlicensed and unnamed by nature — the category is verified, the vendor is whoever reaches you first.", "best_time": "Midday; after a swim", "category": "street", "subcat": "THE STREET", "dishes": [{"name": "Madafu", "note": "green drinking coconut, machete-opened; KES 50–100 the settled rate (obs. 2026)"}, {"name": "The kuna", "note": "hand the nut back and ask — he splits it and cuts a spoon from the shell"}]},
    {"id": "mahamri-stalls", "cat": "market", "tier": "plenty", "priority": 73, "name": "Mahamri mama stalls, Ukunda", "short": "The mahamri mamas", "neighborhood": "Ukunda backstreets & the stage", "maps": "https://www.google.com/maps/search/?api=1&query=Ukunda+town+mahamri", "badge": "", "tags": ["KES 30–50 a piece (obs. 2026-05)", "Walk-in; cash/M-Pesa", "06:30–08:00 or nothing"], "productTags": [], "hours": "From ~05:30; effectively over by 09:00", "why": "Mahamri are triangles of dough flavoured with coconut and cardamom, fried before dawn by women working small pans along Ukunda's back streets and near the matatu stage. They sell for KES 30 to 50 each and are eaten with mbaazi ya nazi, pigeon peas in coconut, and spiced chai. The first batches are gone before 08:00, and the same benches cook biryani and pilau by late morning. There is no seated version worth naming: go early and point.", "address": "", "phone": "", "status": "unverified", "statusChecked": "2026-08-20", "lat": -4.2814, "lng": 39.5662, "hook": "Before dawn, Ukunda's mama stalls fry cardamom-coconut mahamri for chai and pigeon peas; gone by eight.", "signature": "Mahamri na mbaazi with ginger chai, standing up", "verdict": "Set the alarm once — it recalibrates what breakfast means here.", "caveat": "Category solid, names honestly nonexistent; after 08:00 the mahamri are gone or cold.", "best_time": "06:30–08:00", "category": "street", "subcat": "THE STREET", "dishes": [{"name": "Mahamri", "note": "fried from before dawn; the first batches gone before 08:00, KES 30–50 a piece"}, {"name": "Mbaazi ya nazi", "note": "pigeon peas in coconut — the dip the mahamri exists for"}, {"name": "Biryani and pilau", "note": "the same benches turn these out by late morning"}, {"name": "Whole fried fish", "note": "from mid-morning"}]},
    {"id": "mangwe-dens", "cat": "market", "tier": "plenty", "priority": 74, "name": "The mangwe (palm-wine dens)", "short": "The mangwe", "neighborhood": "Ukunda backstreets; Kinondo & Msambweni villages", "maps": "https://www.google.com/maps/search/?api=1&query=Ukunda+Kwale+mnazi+mangwe", "badge": "", "tags": ["Very cheap; no verified price", "Go introduced — via the Kaaribu tour or a trusted local", "Late afternoon"], "productTags": [], "hours": "Afternoons into evening", "why": "Mnazi, the coconut palm wine of the coast, is drunk in mangwe, unmarked rooms in the back streets where selling has traditionally been women's work. Around 2,800 tappers work the coast. The drink was once criminalised; Kwale now licenses it, and in March 2024 the county ordered its roughly 4,000 sellers to reapply. A February 2026 Standard report found mnazi moving into modern lounges, supplied from Kwale and Kilifi groves. An outsider's verified way in is the Kaaribu tour's tasting stop.", "address": "", "phone": "", "status": "confirmed", "statusChecked": "2026-08-20", "hook": "Unsigned palm-wine rooms in Ukunda and the villages, pouring mnazi tapped that morning; go introduced.", "signature": "Morning-tap mnazi, sweet and fizzing, from a shared bottle", "verdict": "With an introduction: one of the coast's realest hours. Without one: don't.", "caveat": "Fermentation continues in the bottle; hygiene varies with the den and the hour. Guests go guided or not at all.", "best_time": "Late afternoon, with a local", "category": "street", "subcat": "THE STREET", "dishes": [{"name": "Mnazi", "note": "coconut palm wine; selling is traditionally a woman's trade"}, {"name": "Going introduced", "note": "via the Kaaribu tour or a trusted local — not a walk-in"}]},
    {"id": "skippers-coliving", "cat": "logistics", "tier": "plenty", "priority": 34, "name": "Skippers Coliving", "short": "Skippers", "neighborhood": "Diani central (near the airstrip)", "maps": "https://www.google.com/maps/search/?api=1&query=Skippers+Coliving+Diani", "badge": "", "tags": ["Rates differ by platform (EUR 500–700/4 wk obs. 2026-08; coliving.com from USD 1,600/mo)", "WhatsApp bookings only", "Thursday live music"], "productTags": ["Starlink", "Est. 2023"], "hours": "Residents 24/7; outside day-use is a favour to ask, not a product", "why": "A plot off Airstrip Road with six en-suite rooms around a pool, built for people who must be online all day: the founders' rule is that a video call should survive a Kwale power cut. Residents come for weeks, not days. For anyone else it is worth knowing for one evening a week, Thursday, when the music night is where the strip's remote workers meet.", "address": "", "phone": "+254 793 870 199", "status": "confirmed", "statusChecked": "2026-10-11", "lat": -4.2999718, "lng": 39.5757395, "hook": "A container-built coworking compound off Airstrip Road, on Starlink and fibre, for people who stay a month.", "person": "Duncan & Camilla (founders, six years living on a boat)", "signature": "The coworking room that simply works", "verdict": "Book it if work is the trip; visit Pallet or Kokkos if work is an hour.", "caveat": "Not a drop-in café: minimum-stay culture (four weeks preferred), day access only in low season and only by asking nicely.", "best_time": "Book weeks ahead; Thursday nights for the music", "best_night": "Thu"},
    {"id": "pilli-pipa", "cat": "logistics", "tier": "plenty", "priority": 38, "name": "Pilli Pipa Dhow Safari", "short": "Pilli Pipa", "neighborhood": "Diani (office); trips from Shimoni", "maps": "https://www.google.com/maps/search/?api=1&query=Pilli+Pipa+Dhow+Safari+Diani", "badge": "", "tags": ["USD 137 adult all-in (obs. 2026-08)", "Book days ahead in season", "Oct–Mar seas"], "productTags": ["Since 1989", "Two dhows"], "hours": "Office daily 07:00–17:00; the day runs ~07:00–17:30", "why": "The office is in Diani but the day starts in Shimoni, ninety minutes south by road, so the pickup is early and the return is late afternoon. What you pay for is the logistics done properly: the boat, the park fees, the lunch on Wasini and the guides, folded into one price. Book it days ahead in season, and on a day when the kusi chop is down.", "address": "", "phone": "+254 724 442 555", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.28756, "lng": 39.58688, "hook": "The long-standing all-in Kisite dhow day: Shimoni jetty, two reef stops, crab lunch on Wasini.", "signature": "The full Kisite day, fees and crab included", "verdict": "Pay the institution price and the day simply works — book it days ahead in season.", "caveat": "A long day with 2.5–3 hours of road; June–August the kusi chop drops visibility. Dolphins are wild — nobody honest promises them.", "best_time": "Oct–Mar for calm and 20 m+ visibility; Jul–Oct for humpbacks", "dishes": [{"name": "Wasini seafood lunch", "note": "coconut soup, crab claws, cassava bites, spiced rice — included"}, {"name": "Scuba add-on", "note": "USD 50 beginner / 40 certified (obs. 2026-08)"}], "guest": true},
    {"id": "h2o-extreme", "web": "https://www.h2o-extreme.com/", "cat": "logistics", "tier": "plenty", "priority": 39, "name": "H2O Extreme", "short": "H2O Extreme", "neighborhood": "Galu Beach (listings name Kenyaways Kite Village; earlier note says Blue Marlin — confirm on WhatsApp)", "maps": "https://www.google.com/maps/search/?api=1&query=H2O+Extreme+Galu+Diani", "badge": "", "tags": ["IKO school — rates by WhatsApp", "Book courses ahead in season", "Kaskazi & kusi windows only"], "productTags": ["IKO", "Since 2003"], "why": "Boris Polo, born and raised in Kenya, opened H2O in 2003 as a surf shack on central Diani, then moved south to Galu because the mid-beach tides and boat traffic made teaching unsafe. That move is the whole argument for the place: on Galu the reef holds a wide, waist-deep lagoon flat at most states of tide. The IKO register lists its 2026 windows as 15 June to 14 September and 20 December to 20 March.", "address": "", "phone": "", "status": "confirmed", "statusChecked": "2026-10-11", "lat": -4.3495618, "lng": 39.5630405, "hook": "The kite school Boris Polo started as a Diani surf shack in 2003, now teaching on the flat Galu lagoon.", "signature": "Learning to ride a trade wind over a flat turquoise lagoon", "verdict": "The seniority pick of the kite beach; confirm current rates by WhatsApp — the site hides them from robots.", "caveat": "Outside the two monsoon windows (roughly Apr–May, Oct–Nov) there is nothing to teach.", "best_time": "Kaskazi mid-Dec–mid-Mar (steadiest); kusi Jun–mid-Sep (stronger)", "hot_this_month": "No kite wind until mid-December: the school says itself there is nothing to teach in October and November (checked 11 Oct 2026)."},
    {"id": "kite254", "web": "https://www.kite254.com/", "cat": "logistics", "tier": "plenty", "priority": 40, "name": "Kite254", "short": "Kite254", "neighborhood": "Galu (Pallet Cafe)", "maps": "https://www.google.com/maps/search/?api=1&query=Kite254+Diani", "badge": "", "tags": ["3-day intro USD 375 (2:1, obs. 2026-08)", "WhatsApp ahead", "Radio helmets"], "productTags": ["IKO", "Ozone kit"], "why": "Kite254 teaches with radio helmets, so a beginner hears the instructor's corrections while the kite is in the air instead of reading hand signals from the beach. The school works from Pallet Cafe on the quiet southern end, on Ozone, Prolimit and Starboard kit, and on light-wind days it switches to wingfoil or hands out paddleboards. Its own season guide is blunt: kaskazi from mid-December to mid-March, kusi from mid-June to mid-September, and little in between.", "address": "", "phone": "+254 719 891 835", "status": "confirmed", "statusChecked": "2026-10-11", "lat": -4.3731018, "lng": 39.5558721, "hook": "A small IKO kite and wingfoil school at Pallet Cafe, where the instructor talks to you through a radio helmet.", "signature": "Radio-helmet lessons on the Galu flat", "verdict": "The tech-forward school; prices published and fair (taster USD 130–210, obs. 2026-08).", "caveat": "Same season trap as all Diani kiting — no wind, no lesson.", "best_time": "Kaskazi for beginners; kusi for power", "hot_this_month": "The kusi has dropped: lessons wait for the kaskazi, from about mid-December (checked 11 Oct 2026)."},
    {"id": "diving-the-crab", "web": "https://www.divingthecrab.com/", "cat": "logistics", "tier": "plenty", "priority": 41, "name": "Diving the Crab", "short": "Diving the Crab", "neighborhood": "Diani central-south (at Nomad)", "maps": "https://www.google.com/maps/search/?api=1&query=Diving+the+Crab+Diani", "badge": "", "tags": ["PADI 5★ IDC — rates on request", "Book the day before", "Oct–Mar visibility"], "productTags": ["Since 1985", "Nitrox"], "hours": "Daily 07:00–17:00", "why": "The Funguo wreck that most Diani divers log was put there on purpose: Diving the Crab re-sank the MV Alpha Funguo off the beach as an artificial reef, and it is now the shop's signature dive. Running since 1985 and trading as Blue Wave Ltd, it holds PADI 5 Star IDC status, teaches tec and freediving, and recently earned a 'Pure Air' rating for its tank fills. Pickup is free within Diani, Kinondo and Galu.", "address": "The Sands at Nomad, Diani Beach Road", "phone": "+254 723 108 108", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.3279941, "lng": 39.5715812, "hook": "Diani's oldest dive shop, running since 1985 from The Sands at Nomad, with its own artificial-reef wreck.", "signature": "The two-tank morning boat to the Funguo wreck", "verdict": "The safe pair of hands for the reef and the wreck; book the day before in season.", "caveat": "June–September kusi brings chop and low visibility — the dive season and kite season are near-opposites.", "best_time": "Oct–Mar; Nov–Feb for whale-shark chances"},
    {"id": "ocean-tribe", "cat": "logistics", "tier": "plenty", "priority": 42, "name": "Ocean Tribe Scuba", "short": "Ocean Tribe", "neighborhood": "Diani (The 41 Beach Club; office at Baobab Beach Resort)", "maps": "https://www.google.com/maps/search/?api=1&query=Ocean+Tribe+Scuba+Diani", "badge": "", "tags": ["2026 price list on site (PDF)", "WhatsApp the day before", "Ten sites within 30 min"], "productTags": ["SSI"], "hours": "Daily dive trips; WhatsApp for schedule", "why": "Ocean Tribe is one of the few SSI shops on a coast where PADI dominates, and it is an SSI instructor-training centre, so the people taking you down are often training the next instructors. It also runs SSI Explorers for children from six. Its trips cover ten local sites within about thirty minutes, from Tiwi Wall to the Alpha Funguo wreck, and it adds full-day dhow runs to Kisite for divers who want the marine park.", "address": "", "phone": "+254 700 934 854", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.2811695, "lng": 39.5900549, "hook": "An SSI dive centre at The 41 Beach Club, with trips to Tiwi Wall, Galu and the Funguo wreck.", "signature": "Tiwi Wall and the Funguo on one morning", "verdict": "Sharp, current, and transparent on paper — the modern pick.", "caveat": "An SSI shop — PADI course-continuers should ask about crossover first. Its whale-shark trips are NOT running for the 2025/26 season, per its own page.", "best_time": "Oct–Mar"},
    {"id": "skydive-swahili", "cat": "logistics", "tier": "plenty", "priority": 43, "name": "Skydive Swahili", "short": "Skydive Swahili", "neighborhood": "Galu (Blue Marlin Beach Hotel)", "maps": "https://www.google.com/maps/search/?api=1&query=Skydive+Swahili+Diani", "badge": "", "tags": ["Tandem USD 350 (obs. 2026-08)", "Book online or WhatsApp", "Closed Tue–Wed"], "productTags": ["KCAA", "USPA"], "hours": "Thu–Mon 08:00–18:00 — closed Tuesday & Wednesday", "why": "The aircraft climbs out of Ukunda airstrip, a few minutes inland, and from 10,000 feet the reef line shows as a white seam holding the turquoise lagoon off Galu. Skydive Swahili flies tandems and an AFF programme for people who want to learn solo, and lands on the beach in front of Blue Marlin. The jump itself takes five to seven minutes; its own FAQ says to plan two to three hours in total, briefing included.", "address": "", "phone": "+254 717 907 907", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.3495618, "lng": 39.5630405, "hook": "Tandem jumps from 10,000 feet over the Galu lagoon, landing on the sand at Blue Marlin Beach Hotel.", "signature": "The lagoon-colour canopy ride down", "verdict": "If the wind gods cancel the kite lesson, go up instead.", "caveat": "Closed Tue–Wed; weather rules everything, reschedule window is generous.", "best_time": "Dry-season mornings (Dec–Mar) for the clearest colours"},
    {"id": "diani-fishing-club", "cat": "logistics", "tier": "plenty", "priority": 45, "name": "Diani Fishing Club", "short": "Fishing Club", "neighborhood": "Diani central", "maps": "https://www.google.com/maps/search/?api=1&query=Diani+Fishing+Club+Kenya", "badge": "", "tags": ["Full day USD 400–600 (obs. 2026-08)", "Book by site form, well ahead Dec–Feb", "Nov–Mar billfish"], "productTags": ["Tag & release"], "hours": "Charters depart early morning", "why": "Off Diani the continental shelf falls away fast into the Pemba Channel, so marlin water is a short run from the beach rather than half a day out. The club's boats, Princess Layla, Shuwari and White Dove, work those drop-offs and the Shimoni banks for blue, black and striped marlin, sailfish, wahoo and dorado. Billfish go back under a tag-and-release rule. In December 2024 its feed reported a Kenya-record 785 lb blue marlin.", "address": "", "phone": "", "status": "confirmed", "statusChecked": "2026-08-20", "hook": "Big-game charters out to the Pemba Channel drop-offs, releasing every billfish they hook.", "signature": "A December sailfish on light tackle", "verdict": "The working charter of the strip — book the season, not the wish.", "caveat": "May–Sep is largely off-season for billfish; the public site masks its phone — use the booking form.", "best_time": "Nov–Mar billfish; Aug–Oct yellowfin"},
    {"id": "whale-shark-adventures", "cat": "logistics", "tier": "plenty", "priority": 46, "name": "Whale Shark Adventures Kenya", "short": "Whale Shark Adv.", "neighborhood": "Diani central", "maps": "https://www.google.com/maps/search/?api=1&query=Whale+Shark+Adventures+Kenya+Diani", "badge": "", "tags": ["Humpback trip EUR 75 (obs. 2026-08)", "WhatsApp ahead", "Hydrophone on board"], "productTags": ["EAWST"], "hours": "Seasonal, sea-state dependent; WhatsApp ahead", "why": "Volker Bassen founded the East African Whale Shark Trust and spent years running spotter-plane research expeditions off Diani before selling seats on the boats. The humpback trips drop a hydrophone over the side, so the whales are often heard before they are seen. He has also pushed publicly for stronger whale-shark protection, and in 2013 drew criticism from ecologists for a proposed netted enclosure, which he defended as a rescue centre.", "address": "", "phone": "+254 720 555 222", "status": "confirmed", "statusChecked": "2026-08-20", "hook": "Seasonal humpback and whale-shark searches led by the founder of the East African Whale Shark Trust.", "person": "Volker Bassen (founder; also founded the East African Whale Shark Trust)", "signature": "Humpback song on the hydrophone, EUR 75", "verdict": "The honest way to meet the migration — sold as a search, not a guarantee.", "caveat": "Blog trail is years old — re-confirm by WhatsApp before promising guests; never sold as guaranteed sightings.", "best_time": "Humpbacks Aug–mid-Oct; whale sharks roughly Nov–Mar, peak Jan–Feb", "hot_this_month": "Whale sharks possible from October, best odds January to March; the humpback trips ended 30 Sep (checked 11 Oct 2026)."},
    {"id": "coral-spirit", "cat": "logistics", "tier": "plenty", "priority": 47, "name": "Coral Spirit — Kongo River", "short": "Coral Spirit", "neighborhood": "Diani north (Kongo river mouth)", "maps": "https://www.google.com/maps/search/?api=1&query=Kongo+River+Diani+canoe", "badge": "", "tags": ["Sunset canoe USD 35–45 (own site USD 35; resellers 45–50) — confirm", "Phone/WhatsApp a day ahead", "Last two hours of light"], "productTags": ["Ten years"], "hours": "Daily 10:00–18:00; sunset departures every day", "why": "The Kongo river, also called Mwachema, comes down off the Shimba Hills and meets the sea at Diani's northern end, beside the coral-stone Kongo Mosque. Coral Spirit takes small groups upstream in traditional dugouts at the end of the day, paddling through the mangroves while herons and kingfishers settle, then back to the beach for drinks. It also runs paddleboarding on the same flat water and a beach bonfire barbecue as an add-on.", "address": "", "phone": "+254 716 440 223", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.2602353, "lng": 39.5981344, "hook": "A two-hour dugout-canoe paddle up the Kongo river mangroves at dusk, from Diani's northern tip.", "signature": "The sunset dugout through the mangroves — USD 43", "verdict": "Do it once and the river end of Diani makes sense forever.", "caveat": "The whole web store shows 'sold out' — booking is by phone/WhatsApp in practice; after rains the river runs murky.", "best_time": "The last two hours of light, on a rising tide"},
    {"id": "kaaribu-tour", "web": "https://kaaribu.com/experience/diani-street-food-and-market-tour", "cat": "logistics", "tier": "plenty", "priority": 48, "name": "Kaaribu — Ukunda Street Food & Market Tour", "short": "Kaaribu tour", "neighborhood": "Ukunda (meets at Tsunami Garden Cafe)", "maps": "https://www.google.com/maps/search/?api=1&query=Tsunami+Garden+Cafe+Ukunda", "badge": "", "tags": ["USD 25 direct (obs. 2026-08)", "Book a day ahead", "Includes an mnazi tasting"], "productTags": ["Registered co."], "hours": "Bookable year-round; 1.5 h; morning slot best", "why": "Most visitors to Diani never cross the main road into Ukunda, where the town actually eats. This walk starts at Tsunami Garden Cafe and goes into Ukunda's trading lanes, then to a kibandaski for cardamom-coconut porridge, viazi karai and chapati with beans. It ends at a mangwe, the unsigned palm-wine den where mnazi is poured; without an introduction an outsider would not get past the door. Kaaribu Experiences is a registered company with an office in Nairobi.", "address": "", "phone": "+254 732 905 343", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.2914957, "lng": 39.564288, "hook": "A ninety-minute walk through Ukunda's market lanes and street kitchens, ending with palm wine.", "signature": "The mangwe stop — mnazi with an introduction", "verdict": "Spend the 25 dollars before any restaurant money: everything else in Ukunda makes sense after it.", "caveat": "Morning slot for the fullest market and lowest heat; no named guide published — the company registration is the verification.", "best_time": "Morning", "dishes": [{"name": "Uji — Swahili porridge", "note": "wheat, cardamom, coconut — the opener most visitors never meet"}, {"name": "Mnazi at the mangwe", "note": "fresh palm wine with a local introduction"}], "subcat": "THE STREET"},
    {"id": "kaya-kinondo", "web": "https://kayakinondotrails.com/", "cat": "mainland", "tier": "plenty", "priority": 49, "name": "Kaya Kinondo Sacred Forest", "short": "Kaya Kinondo", "neighborhood": "Kinondo", "maps": "https://www.google.com/maps/search/?api=1&query=Kaya+Kinondo+Sacred+Forest+Kenya", "badge": "", "tags": ["Non-resident KES 2,000 incl. guide (listing; older sources KES 800) — agree before starting", "Phone ahead; M-Pesa preferred", "Morning or from 15:00; last entry ~16:00"], "productTags": ["UNESCO 2008"], "hours": "Daytime; operators run ~10:00 and 15:00 departures — reserve ahead", "why": "Kaya Kinondo was closed to outsiders until 2001, when the Digo elders offered a sacrifice to the ancestors and opened it to guided visits: Kenya's first kaya ecotourism project. You remove any hat, tie on a black kaniki and promise not to kiss inside. The guide names medicinal trees, among them a 'pimple tree' used for acne, and stops short of the main shrine, which only elders may enter. Proceeds go to the village, schools and the forest.", "address": "", "phone": "+254 745 797 653", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.3933458, "lng": 39.5470623, "hook": "A sacred Digo forest you may enter only wrapped in a black kaniki cloth and led by a village guide.", "signature": "The guided walk in the kaniki — 60–90 minutes inside a living shrine", "verdict": "The most important hour on this coast; treat it as a visit to a church, because it is one.", "caveat": "Stay on the path, take nothing — not a leaf; no smoking, no alcohol, no public affection; photography restricted, ask the guide. The fee is opaque — agree it clearly before starting.", "best_time": "Morning, or from 15:00 — midday under the canopy edge is brutal", "dishes": [{"name": "The kaniki walk", "note": "wrap the provided black cloth, remove headwear, follow the guide"}, {"name": "Digo dance session", "note": "the all-female troupe with kayamba rhythms — pre-book"}, {"name": "Seedling planting", "note": "buy and plant a native seedling from the community nursery"}], "guest": true},
    {"id": "colobus-conservation", "cat": "mainland", "tier": "plenty", "priority": 50, "name": "Colobus Conservation", "short": "Colobus Conservation", "neighborhood": "Diani south", "maps": "https://www.google.com/maps/search/?api=1&query=Colobus+Conservation+Diani", "badge": "", "tags": ["Eco-tour ~1 h; non-resident KES 750–1,000 reported (unofficial) — cashless", "Walk-in in hours; groups pre-arrange", "Morning, when troops move"], "productTags": ["Est. 1997", "AZA"], "hours": "Mon–Sat ~08:30–16:00; Sunday hours reported differently (mornings only vs closed) — call ahead", "why": "Diani Beach Road was cut through coral-rag forest in 1971, and the Angolan colobus that live on either side kept trying to cross it. Colobus Conservation started in 1997 in response and began stringing rope bridges over the tarmac; it now counts more than forty across the region, and surveys from 2004 to 2020 credit them with a 70 percent rise in safe crossings. Vehicles still injure or kill around 55 primates a year on the strip.", "address": "", "phone": "+254 711 479 453", "status": "confirmed", "statusChecked": "2026-10-11", "lat": -4.3444108, "lng": 39.5649514, "hook": "The Diani charity behind the rope 'colobridges' over Beach Road, with a rescue centre you can walk round.", "signature": "The eco-tour past the rehab enclosures — the fee funds the bridges", "verdict": "Go, pay, and then drive the strip slowly forever after.", "caveat": "A working rescue facility, not a petting zoo — no handling. Report injured monkeys to the 24 h line.", "best_time": "Morning", "dishes": [{"name": "Guided eco-tour", "note": "45–60 minutes; Mon–Sat 08:30–16:00; cashless"}, {"name": "Colobridge spotting", "note": "free and real — rope ladders overhead along the strip; drive slow"}], "guest": true},
    {"id": "kisite-mpunguti", "cat": "mainland", "tier": "plenty", "priority": 51, "name": "Kisite-Mpunguti Marine National Park", "short": "Kisite", "neighborhood": "Off Shimoni", "maps": "https://www.google.com/maps/search/?api=1&query=Kisite+Mpunguti+Marine+National+Park", "badge": "", "tags": ["Non-resident USD 25 adult / 15 child (KWS schedule of Oct 2025, still current)", "Via operator (fees folded in) or KWSPay — cashless", "Oct–Mar seas"], "productTags": ["Est. 1978", "39 km²"], "hours": "Day visits, boats work the tides", "why": "Kisite-Mpunguti was gazetted in 1978 and covers 39 square kilometres of coral islets eleven kilometres off Shimoni, against the Tanzanian border. Three dolphin species use it: Indo-Pacific bottlenose on the reefs year-round, humpback dolphins in the channels, and spinners in pods of fifty to two hundred. From July to October humpback whales pass on their way north from Antarctic waters, and researchers have tracked them here since 2011. Single-use plastics are banned inside.", "address": "", "phone": "0800 597 000 (KWS toll-free)", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.71977, "lng": 39.37165, "hook": "A no-take marine park of coral islets off Shimoni, where bottlenose, humpback and spinner dolphins feed.", "signature": "Inner Kisite's hard-coral wall on a spring-clear morning", "verdict": "The reason the dhow day exists; go with the tide and the season, not against them.", "caveat": "In December–January many day boats converge on the same reefs mid-morning; wild dolphins, no guarantees.", "best_time": "Oct–Mar for 20 m visibility; Jul–Oct for whales", "hot_this_month": "Calmer seas return with the kaskazi from November; the dolphins are year-round."},
    {"id": "shimoni-caves", "cat": "mainland", "tier": "plenty", "priority": 52, "name": "Shimoni Slave Caves", "short": "Shimoni Caves", "neighborhood": "Shimoni", "maps": "https://www.google.com/maps/search/?api=1&query=Shimoni+Slave+Caves+Kenya", "badge": "", "tags": ["Small cash fee — KES 100–500 reported, unverified", "Walk-in with the community guide", "After the Wasini lunch"], "productTags": ["NMK-assisted"], "hours": "Daytime; sources differ (two sessions vs 08:30–18:00) — call ahead", "why": "The caves sit a few steps from the Shimoni jetty, so most visitors see them in the last hour of the dhow day, tired and sunburnt; come instead in the morning, before the boats return, and the guide has time. The site is run by a village committee with help from the national museums, and the entry money pays for teachers and medicine in Shimoni. Bring small notes: the fee is not published, and it is asked in cash at the gate.", "address": "", "phone": "", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.6474, "lng": 39.38051, "hook": "Coral caves by the Shimoni jetty where enslaved people were held for the dhows to Zanzibar and Pemba.", "signature": "The twenty heavy minutes with the guide — that is the visit", "verdict": "Go with the guide and let it be heavy; it is the point of Shimoni.", "caveat": "Bats, slippery coral steps; no verified fee to print — carry small cash and take the ticket offered.", "best_time": "Tacked onto the dhow day, after lunch"},
    {"id": "wasini-boardwalk", "cat": "mainland", "tier": "plenty", "priority": 53, "name": "Wasini Women's Coral Boardwalk", "short": "Wasini Boardwalk", "neighborhood": "Wasini Island", "maps": "https://www.google.com/maps/search/?api=1&query=Wasini+women+boardwalk+coral+garden", "badge": "", "tags": ["Small entry fee (KES 200 reported, unverified)", "Walk-in; women's-group guides at the gate", "High tide is the stranger sight"], "productTags": ["Since 1978"], "hours": "Daylight, around the lunch stop", "why": "At high tide the sea pushes in under the planks and floods the dead coral heads, so the same walk looks completely different depending on when the dhow lands. KWS staff and villagers built the boardwalk with Kenyan and European biodiversity money, and the Wasini Women Group, around seventy members, runs it and keeps the fees for village welfare. The group's enterprise goes back to 1978. A small curio shop sits at the exit.", "address": "", "phone": "", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.659, "lng": 39.3655, "hook": "A raised wooden walkway over fossil coral and mangrove at the edge of Wasini village, run by its women.", "signature": "The half hour after lunch, water moving under the fossil coral", "verdict": "The gentlest thing on the dhow day — give the women the half hour and the fee.", "caveat": "Planks are weathered in stretches: flip-flops fine, heels absurd.", "best_time": "High tide"},
    {"id": "shimba-hills", "cat": "mainland", "tier": "plenty", "priority": 54, "name": "Shimba Hills National Reserve", "short": "Shimba Hills", "neighborhood": "Inland Kwale (gate 31 km from Diani)", "maps": "https://www.google.com/maps/search/?api=1&query=Shimba+Hills+National+Reserve", "badge": "", "tags": ["Non-resident USD 50 / child 25 (KWS Oct 2025 schedule, still current)", "Pay via KWSPay — cashless", "Be at the gate at 06:00"], "productTags": ["Est. 1968", "Sable"], "hours": "Gates 06:00–18:00 daily", "why": "Shimba Hills was first protected as forest in 1903 and gazetted as a reserve in 1968; at 192.5 square kilometres it is the largest block of coastal rainforest left in Kenya. KWS describes its sable as the country's last breeding herd, best seen early around Giriama Point as they move down to drink. The ranger-escorted path to Sheldrick Falls takes up to an hour each way and ends at a drop of about 25 metres.", "address": "", "phone": "0800 597 000 (KWS)", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.197192, "lng": 39.441794, "hook": "A misty coastal rainforest reserve inland of Diani, home to Kenya's only sable antelope and a 25 m waterfall.", "signature": "Sable on the glades at 06:30, mist burning off toward the sea", "verdict": "The one-day green counterweight to the beach — early gate or don't bother.", "caveat": "Forest, not savannah: do not promise Mara density. Non-resident fee rose to USD 50 in the Oct 2025 schedule — old blogs still quote KES 300.", "best_time": "Gate at 06:00; sable graze early", "dishes": [{"name": "Sheldrick Falls walk", "note": "ranger-escorted from the trailhead; water and real shoes"}, {"name": "The viewpoints", "note": "ocean panoramas off the glade edges"}]},
    {"id": "mikoko-pamoja", "cat": "mainland", "tier": "plenty", "priority": 55, "name": "Mikoko Pamoja (Gazi Bay)", "short": "Mikoko Pamoja", "neighborhood": "Gazi", "maps": "https://www.google.com/maps/search/?api=1&query=Mikoko+Pamoja+Gazi+Bay", "badge": "", "tags": ["Donation/guiding fee — arrange ahead", "Contact via mikokopamoja.org", "Morning low-to-rising tide"], "productTags": ["Equator Prize", "Plan Vivo"], "hours": "Visits by arrangement via the project", "why": "Mikoko pamoja means 'mangroves together'. The village at Gazi Bay protects 117 hectares of mangrove and replants several thousand trees a year, and was the first community anywhere to fund that work by selling blue-carbon credits. The money has gone into wells, school supplies and repairs. In July 2026 a German state secretary's delegation went out on the bay to see the plots. Visits mean an hour with the project team among the replanted rows.", "address": "", "phone": "", "status": "confirmed", "statusChecked": "2026-10-11", "lat": -4.4344893, "lng": 39.5096133, "hook": "The Gazi Bay village project that pays for wells and schoolbooks by selling mangrove carbon credits.", "signature": "The replanted plots with the project team", "verdict": "A working conservation office, not an attraction — arrange ahead and pay fairly for guiding time.", "caveat": "Combine with the village boardwalk and a Gazi lunch; do not expect fixed hours.", "best_time": "Morning, low-to-rising tide"},
    {"id": "diani-turtle-watch", "cat": "mainland", "tier": "plenty", "priority": 58, "name": "Diani Turtle Watch", "short": "Turtle Watch", "neighborhood": "Diani–Galu beachfront (programme, no premises)", "maps": "https://www.google.com/maps/search/?api=1&query=Diani+Turtle+Watch+Diani+Beach", "badge": "", "tags": ["Free/donation (unverified)", "Follow @dianiturtlewatch; ask your hotel's beach team", "Releases at dawn/dusk, day-of notice"], "productTags": ["Since 2012"], "hours": "Nest excavations and releases announced ad hoc", "why": "Diani Turtle Watch started in 2012 as an offshoot of Local Ocean Trust in Watamu. Its monitors walk the beach each morning looking for tracks, move nests at risk from tides or people into hatcheries on hotel frontages, and wait 55 to 75 days for them to hatch. They also answer stranding calls and do post-mortems, which keep turning up plastic. One hotel hatchery alone reported nearly 1,300 hatchlings in its second season.", "address": "", "phone": "", "status": "confirmed", "statusChecked": "2026-08-20", "hook": "A volunteer turtle patrol that moves threatened nests to hotel hatcheries and calls releases at short notice.", "signature": "A hatchling release at dusk — the real thing, announced hours ahead", "verdict": "Follow the channel, and if a release is called while you are here, drop everything.", "caveat": "A programme, not premises: nothing is guaranteed on any given day.", "best_time": "Warmer months cluster the nests; releases announced day-of"},
    {"id": "diani-art-club", "web": "https://diani-artclub.com/", "cat": "shop", "tier": "plenty", "priority": 60, "name": "Diani Art Club", "short": "Art Club", "neighborhood": "Ukunda (opposite the GPS petrol station)", "maps": "https://www.google.com/maps/search/?api=1&query=Diani+Art+Club+Ukunda", "badge": "", "tags": ["Commissions by WhatsApp", "Walk-in", "Afternoon"], "productTags": [], "hours": "Mon–Sat 09:00–18:30; Sun 10:00–18:30 Sep–Feb only", "why": "Jimmy, the resident portrait painter, works from the gallery and takes commissions, so you can sit for a likeness or leave a photo and collect the canvas later in the trip. The walls run from large abstracts by Kenyan painters to Maasai beadwork and handcraft. It keeps published hours, including Sundays from September to February, which is unusual on this road, and it books safaris on the side.", "address": "", "phone": "+254 703 648 892", "status": "confirmed", "statusChecked": "2026-08-20", "hook": "A small roadside gallery of Kenyan painting near the GPS petrol station, with a portraitist on site.", "verdict": "Go for the painting wall, not a museum experience.", "caveat": "Small and commercial; find it by the petrol-station landmark — it is not on the map apps.", "best_time": "Afternoon"},
    {"id": "carrefour-diani", "cat": "shop", "tier": "plenty", "priority": 65, "name": "Carrefour Diani (Centre Point)", "short": "Carrefour", "neighborhood": "Ukunda junction", "maps": "https://www.google.com/maps/search/?api=1&query=Carrefour+Diani+Centre+Point", "badge": "", "tags": ["Supermarket pricing", "Walk-in", "Morning restock after the market run"], "productTags": [], "hours": "Typically ~08:30–21:00 — unverified first-party", "why": "Majid Al Futtaim opened Kwale County's first Carrefour at Diani Centre Point Plaza in February 2021, a Carrefour Market format with 1,000 square metres of selling floor in its first phase. For a galley the useful parts are the chilled ones: a fresh fish counter, butchery, dairy and bakery, plus dry stores. Kentaste's coconut milk and cream, made a short drive inland, sit on its shelves.", "address": "", "phone": "", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.2908292, "lng": 39.5852718, "hook": "A Carrefour Market at Centre Point, Ukunda junction: fish counter, butchery, bakery and cold stores.", "verdict": "Market first for the living produce, Carrefour second for everything that must stay cold.", "caveat": "Imported specialty depth (cheese, charcuterie, wine) stays thinner than Nairobi — plan around it.", "best_time": "Morning", "buy": "Dairy, dry stores, back-up protein, Kentaste coconut cream and oil.", "galley": "Do the market at 07:00, the fish landing by 08:00, Carrefour at 09:00 — one loop, one morning."},
    {"id": "chandarana-diani", "cat": "shop", "tier": "plenty", "priority": 66, "name": "Chandarana Foodplus (Baharini Plaza)", "short": "Chandarana", "neighborhood": "Diani central", "maps": "https://www.google.com/maps/search/?api=1&query=Chandarana+Foodplus+Diani", "badge": "", "tags": ["Imported & Indian-Kenyan lines", "Walk-in", "Quietest mid-afternoon"], "productTags": [], "hours": "~08:00–21:00 daily (directory-sourced)", "why": "Chandarana is a Kenyan family chain, and its Diani branch at Baharini Plaza carries what the coast's own kitchens use: whole spices and masalas, ghee, atta and lentils from the Indian-Kenyan pantry, alongside imported goods, wine and spirits, fresh meat and produce. If a recipe calls for cardamom pods by the hundred gram rather than a jar, this is where to find them on the strip.", "address": "", "phone": "+254 712 354 955", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.3076708, "lng": 39.5770218, "hook": "Chandarana's mid-strip branch at Baharini Plaza: spices, ghee, atta, wine and imported lines.", "verdict": "The pantry for the coast's actual cooking.", "caveat": "Chain site in maintenance mode — hours are directory-sourced only.", "best_time": "Mid-afternoon", "buy": "Whole spices, ghee, atta, pulses (mbaazi!), pickles, Indian-Kenyan brands.", "galley": "Buy mbaazi (pigeon peas) dry and cook them in coconut for the real coast breakfast."},
    {"id": "naivas-ukunda", "cat": "shop", "tier": "plenty", "priority": 67, "name": "Naivas Ukunda (The Gate Mall)", "short": "Naivas", "neighborhood": "Ukunda", "maps": "https://www.google.com/maps/search/?api=1&query=Naivas+Ukunda+Gate+Mall", "badge": "", "tags": ["Cheapest of the three chains", "Walk-in", "Early, with the market in the same run"], "productTags": [], "hours": "Directory hours conflict (08:30–21:00 vs 07:00–22:00) — call first", "why": "Naivas opened in Ukunda's Gate Mall in November 2015, taking a unit first booked for the now-failed Uchumi chain. Kenya's largest homegrown supermarket group prices for residents rather than beach visitors, and the store has a bakery, butchery and liquor section. It sits on the inland side of the junction, so it fits naturally into a run that starts at the Ukunda produce market.", "address": "", "phone": "", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.281285, "lng": 39.5662791, "hook": "Naivas at The Gate Mall in Ukunda, the supermarket where residents shop at town prices.", "verdict": "Staples at town prices; nothing romantic, everything useful.", "caveat": "No first-party hours; aggregators conflict — call before an early run.", "best_time": "Early", "buy": "Dry staples, cleaning, crates of water and soda at local prices.", "galley": "Do bulk here; save the beach-road chains for the cold chain."},
    {"id": "kentaste", "cat": "logistics", "tier": "plenty", "priority": 68, "name": "Kentaste coconut works, Ukunda", "short": "Kentaste", "neighborhood": "Ukunda outskirts", "maps": "https://www.google.com/maps/search/?api=1&query=Kentaste+Ukunda+Kenya", "badge": "", "tags": ["Buy the products on the strip", "Trade enquiries only", "n/a"], "productTags": ["Organic", "Fair for Life"], "hours": "A working factory — no public tours verified", "why": "Kentaste was set up to give coast smallholders a steady price for nuts that mostly fell unused under millions of palms. It now buys from about 2,700 to 3,500 farmers, most of them certified organic and Fair for Life, and turns their coconuts into milk, cream, virgin oil, flour, desiccated coconut and baked coconut chips, which won New Product of the Year at the 2023 Africa Food Awards. Its factories are at Kwale and Malindi.", "address": "", "phone": "+254 715 767 675", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.281409, "lng": 39.566161, "hook": "The coconut processor behind Kenya's supermarket coconut milk, with a factory at Kwale.", "verdict": "A story to know, not a place to visit — stock the pantry from the strip's shelves.", "caveat": "No public tours; the plot is unpublished — coordinates are town-level only.", "buy": "Coconut cream, virgin oil, desiccated — made from south-coast nuts.", "galley": "The honest substitute for flying in tinned coconut: local, certified, consistent."},
    {"id": "akamba-handicraft", "web": "https://akambahandicraftcoop.com/", "cat": "mainland", "tier": "plenty", "priority": 69, "name": "Akamba Handicraft Co-operative", "short": "Akamba Co-op", "neighborhood": "Mombasa — Changamwe (via Dongo Kundu)", "maps": "https://www.google.com/maps/search/?api=1&query=Akamba+Handicraft+Cooperative+Mombasa", "badge": "", "tags": ["70–80% of each sale to the carver", "Walk-in; phone for groups", "Weekday mornings, sheds fullest"], "productTags": ["Est. 1963", "~2,800 members"], "hours": "Daytime Mon–Sat — phone ahead", "why": "This is a workplace, not a shop with a workshop attached: the sheds are open, the noise is real, and nobody stops working because you walked in. The co-operative sits in industrial Changamwe, off the Port Reitz road toward the airport, which is why the sensible way to see it is on the way to a flight. The store prices are fixed and fair, and a piece carries the carver's name if you ask.", "address": "", "phone": "+254 746 233 118", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.0197597, "lng": 39.6272832, "hook": "Kenya's largest woodcarving co-operative, in Mombasa's Changamwe: open sheds where carvers work by hand.", "signature": "A carving bought in the shed it was cut in", "verdict": "Pair it with an airport run and skip every beach-road 'ebony' stall forever.", "caveat": "Industrial Changamwe, not the south coast. Real mpingo is heavy and dark to the core — shoe-polished fakes are coastwide; weight and end-grain tell the truth.", "best_time": "Weekday morning"},
    {"id": "biashara-street", "cat": "mainland", "tier": "plenty", "priority": 70, "name": "Biashara Street kanga houses", "short": "Biashara Street", "neighborhood": "Mombasa (day trip)", "maps": "https://www.google.com/maps/search/?api=1&query=Biashara+Street+Mombasa+kanga", "badge": "", "tags": ["Kangas sold in pairs (doti); bargaining standard", "Walk-in", "Morning, with Old Town"], "productTags": ["Since 1887"], "hours": "Mon–Sat business hours (unverified); quieter Friday midday", "why": "Nearly every kikoi and kanga sold on Diani's beach stalls is a factory print bought by the bale here, on Biashara Street in Mombasa's old commercial core. Mali ya Abdulla, the house of Kaderdina Hajee Essak, has traded on this street since 1907, and its name turns up printed into kanga borders. Each kanga carries a Swahili proverb along its edge, which is why buyers read the cloth before they look at the colour.", "address": "", "phone": "", "status": "confirmed", "statusChecked": "2026-08-20", "lat": -4.0554398, "lng": 39.6696332, "hook": "Mombasa's wholesale kanga and kikoi street, where tailors hem your cloth while you wait.", "signature": "A doti of kangas with a proverb you actually understand", "verdict": "Buy the cloth at its source and have it hemmed while you drink the street's chai.", "caveat": "Kanga proverbs (majina) matter — have a Swahili speaker translate before you gift one. Named shops are leads; the street trade itself is the institution.", "best_time": "Morning; combine with Old Town"},
    {"id": "manyatta-club", "cat": "shop", "tier": "plenty", "priority": 32, "name": "Manyatta Resort & Disco Lounge", "short": "Manyatta", "neighborhood": "Diani central", "maps": "https://www.google.com/maps/search/?api=1&query=Manyatta+Club+Diani", "badge": "", "tags": ["Cash, walk-in", "Weekend nights"], "productTags": [], "hours": "Unpublished", "why": "Manyatta's pull is that it fills early: one Business Daily reviewer found it busy by 20:30 on a weekend, on a strip where clubs usually start after eleven. It is an open-plan makuti bar with DJs, nyama choma and a mostly Kenyan crowd, and buying spirits by the bottle works out cheaper for a group. The place has rebranded as Manyatta Resort & Disco Lounge, adding rooms from KSh 4,000 and a rooftop lounge.", "address": "Diani Beach Road, near Msitu Kwetu Cottages", "phone": "", "status": "unverified", "statusChecked": "2026-08-20", "lat": -4.3210952, "lng": 39.5727613, "hook": "A makuti-roofed bar and disco on Diani Beach Road, now selling itself as Manyatta Resort & Disco Lounge.", "verdict": "For a chef comfortable in local bars, the real one; guests may want the beach instead.", "caveat": "No dated 2026 first-party post or review confirmed; active social channels exist but aggregator '2026' titles are automatic. Go with a local driver who knows the door, and confirm the night first.", "best_time": "Weekend nights", "best_night": "Fri|Sat"}
