  const NEIGHBORHOODS = [{"name": "Diani North — the river end", "desc": "Where the strip runs out into estuary, baobab and a coral mosque that has outlived every hotel", "maps": "https://www.google.com/maps/search/?api=1&query=Kongo+Mosque+Diani+Beach+Kenya"}, {"name": "Diani Central", "desc": "Hotels, bars and dive shops back to back behind the whitest sand, and a week here needs no car", "maps": "https://www.google.com/maps/search/?api=1&query=Diani+Beach+central+Kenya"}, {"name": "Galu & the southern strip", "desc": "The beach changes its name south of Nomad, and the pace of the day drops by half", "maps": "https://www.google.com/maps/search/?api=1&query=Galu+Beach+Kenya"}, {"name": "Ukunda town", "desc": "Twenty minutes from the sunbeds: matatus, banks, markets, the airstrip, and the food locals actually eat", "maps": "https://www.google.com/maps/search/?api=1&query=Ukunda+town+Kenya"}, {"name": "Tiwi", "desc": "Wade the river mouth on the ebb and the beach on the far side is nearly empty", "maps": "https://www.google.com/maps/search/?api=1&query=Tiwi+Beach+Kenya"}, {"name": "Likoni & Dongo Kundu — the arrival", "desc": "The old ferry or the new bypass: since August 2024 the south coast finally has a choice of front door", "maps": "https://www.google.com/maps/search/?api=1&query=Dongo+Kundu+bypass+Mombasa"}, {"name": "Kinondo & Chale point", "desc": "Rural Digo country behind the last of the sand, where the forest is a shrine", "maps": "https://www.google.com/maps/search/?api=1&query=Kinondo+Kwale+Kenya"}, {"name": "Gazi & Msambweni", "desc": "A mangrove village the scientists know by name, then kilometres of sand with nobody on it", "maps": "https://www.google.com/maps/search/?api=1&query=Gazi+Bay+Kwale+Kenya"}, {"name": "Shimoni & Wasini", "desc": "A dhow harbour heavy with history, and across the channel an island with no roads and no cars", "maps": "https://www.google.com/maps/search/?api=1&query=Shimoni+Kenya"}];
  const WALKS = [{"name": "Sunrise on the strip", "desc": "The emptiest hour of the resort day, and the fishermen are already pushing out", "maps": "https://www.google.com/maps/search/?api=1&query=Diani+Beach+Kenya"}, {"name": "Kongo Mosque & the river mouth", "desc": "Baobabs, an estuary you can wade at low water, and a coral mosque still in daily use", "maps": "https://www.google.com/maps/search/?api=1&query=Kongo+Mosque+Diani+Beach+Kenya"}, {"name": "The reef-flat walk", "desc": "Twice a month the lagoon drains and hands you two hours of seabed, from central Diani to Galu", "maps": "https://www.google.com/maps/search/?api=1&query=Diani+Beach+reef+flat+Kenya"}, {"name": "Ukunda market & town walk", "desc": "The matatu stage, the kanga shops, the covered market and lunch at a kibanda: the strip's engine room", "maps": "https://www.google.com/maps/search/?api=1&query=Ukunda+town+market+Kenya"}, {"name": "Gazi Bay mangrove edge", "desc": "The village shore of the mangrove bay every scientist in the field knows by name", "maps": "https://www.google.com/maps/search/?api=1&query=Gazi+Bay+mangroves+Kwale+Kenya"}, {"name": "Shimoni history walk", "desc": "The caves, the 1880s company ruins, the working jetty and the channel to Wasini", "maps": "https://www.google.com/maps/search/?api=1&query=Shimoni+jetty+Kenya"}];
