  const PHOTOS = [{"src": "/terroir/Diani-Kwale/img/diani-1.jpg", "caption": "The strip at low water — the lagoon empties twice a day, and the tideline of seagrass is habitat, not litter.", "credit": "Nicor · CC BY 3.0 · Wikimedia Commons"}, {"src": "/terroir/Diani-Kwale/img/diani-2.jpg", "caption": "A fishing skiff on the seagrass flat. The Diani–Chale fishery counts some 570 artisanal fishers working the monsoon-and-moon calendar.", "credit": "Margarida Taborda · CC BY-SA 4.0 · Wikimedia Commons"}, {"src": "/terroir/Diani-Kwale/img/diani-3.jpg", "caption": "Angolan black-and-white colobus, photographed in Kwale. An average of 55 monkeys a year are still hit on the beach road — hence the rope bridges.", "credit": "Jan Ebr · CC BY 4.0 · Wikimedia Commons (iNaturalist)"}];
  const GEMS = [{"id": "gem-mnazi", "name": "Mnazi — the tapper's wine", "tag": "Food gem", "title": "The wine that must be drunk today", "pattern": "mnazi", "story": "Palm wine, tapped from the coconut palm and drunk the same day. How it is made, and how to drink it with the people who make it, is in La liste at the foot.", "body": "", "where": "Tasted respectfully on the Kaaribu tour's mangwe stop, or at the Kaya Kinondo village visit"}, {"id": "gem-colobridge", "name": "The colobridges", "tag": "Place gem", "title": "Rope ladders over the traffic", "pattern": "colobridge", "story": "The road that made Diani — cut through coral-rag forest in 1971 — bisected the canopy home of the Angolan black-and-white colobus. Cars still hit an average of 55 monkeys a year on the nine-kilometre strip. The community answer, since 1997, is Colobus Conservation's colobridges: 29 rope ladders strung over Diani Beach Road (plus four over private drives), so the troops cross above the traffic. Look up anywhere on the strip and you will eventually see the crossing happen — black-and-white commas moving hand over hand over the matatus.", "body": "", "where": "Overhead along Diani Beach Road; the rescue centre tours Mon–Sat 08:30–16:00"}, {"id": "gem-jadini", "name": "Jadini", "tag": "Name gem", "title": "The hotel that named a forest", "pattern": "Jadini", "story": "Diani's remembered first hotel, Jadini — built by the Trench family, who arrived in the 1930s — is an acronym: Jack, Anne and Dan Trench plus '-ini', the Swahili locative ending, roughly 'the place of J-A-D'. The name outgrew the building: the surviving patches of coastal hardwood at the strip's south end are still called the Jadini Forest, though botanists point out it is more correctly the Diani Forest. The hotel closed in the 2010s contraction; the monkeys kept the name.", "body": "", "where": "The forest patches around Colobus Conservation, southern strip"}, {"id": "gem-fortytwo", "name": "Four Twenty South", "tag": "Name gem", "title": "Named by latitude, for want of landmarks", "pattern": "Four Twenty South", "story": "When the Portsmouth family bought May's Cottages on Galu beach in 1966 — it had opened to guests in 1958 — they renamed it Four Twenty South, for the latitude 4°20'S, 'because there were no landmarks in the forest'. That sentence is the best census of 1960s Diani that exists: Ukunda was one duka and a petrol station, the land behind the sand was coconut plantation, and the address system was the sky.", "body": "", "where": "Four Twenty South cottages still trade under the name at Galu"}, {"id": "gem-madafu", "name": "Madafu at the river mouth", "tag": "Food gem", "title": "One tree, one beach, seven centuries", "pattern": "madafu", "story": "The green drinking coconut, topped with a panga and drunk from the husk. Where it comes from, and what to ask for once it is empty, is in La liste at the foot of this guide.", "body": "", "where": "Kongo Beach and the whole strip, from any vendor with a panga"}, {"id": "gem-kupaka", "name": "Samaki wa kupaka", "tag": "Food gem", "title": "The smear", "pattern": "samaki wa kupaka", "story": "Kupaka means 'to smear': grilled fish, then spiced coconut cream, then the coals again. The whole story, and how to tell a real one, is in La liste at the foot.", "body": "", "where": "Ukunda's Swahili kitchens; grill shacks along the strip"}];
  const TABLES = {"grande": {"title": "Les Grandes Tables", "desc": "The rooms worth planning a day around: the coral cave, the canvas on the sand, the new wave, the house tables, and the landings that feed them all.", "sections": [{"label": "The famous rooms", "desc": "Three rooms worth a booking and a taxi: the coral cave, the canvas tent on the sand at Galu, and the strip's most complete kitchen.", "ids": ["ali-barbours-cave", "sails-almanara", "nomad-beach-bar"]}, {"label": "The new wave", "desc": "Two kitchens trying something on the beach road: a Japanese family's sushi house and a palm-shaded bistro.", "ids": ["shashin-ka", "asha-bistro"]}, {"label": "The house tables", "desc": "Three houses that cook for people who are not staying, if you ask first: beside the sacred forest, with no meal times, and on the island.", "ids": ["kinondo-kwetu", "the-maji", "chale-island"]}, {"label": "Where the boats land", "desc": "Where the fish and the vegetables come ashore: the landing you can walk to, the channel port, and the new covered market.", "ids": ["mwaepe-landing", "shimoni-landing", "diani-modern-market"]}]}, "petite": {"title": "Les Petites Tables", "desc": "Ukunda's kitchens, the Italian residency, the breakfast rooms, the fire, where the residents eat, the beach rooms and the old houses — character over ceremony, most of it inland of the sand.", "sections": [{"label": "The Swahili kitchens", "desc": "Ukunda's kitchens, where the strip's staff eat: biryani, nyama choma and pilau at resident prices.", "ids": ["moiz-swahili", "karafuu", "swahili-pot"]}, {"label": "The Italian residency", "desc": "The Italian residency of the beach road: the wood oven that anchors it, and the neighbour a few doors along.", "ids": ["leonardos", "aniellos"]}, {"label": "The breakfast tables", "desc": "Coffee and the first meal: the strip's café since 2000, the deaf-staffed café on the sand, and German bread.", "ids": ["kokkos", "pallet-cafe-diani", "diani-bakehouse"]}, {"label": "The fire", "desc": "Fish over charcoal at the landing and meat at the junction: the fire where the coast cooks.", "ids": ["mwaepe-fishermen", "colobus-shade", "ukunda-junction-vendors"]}, {"label": "Where the residents eat", "desc": "Where the people who run the strip eat and drink after work: a Belgian bistro, the late kitchen, and the bar team with a ranking.", "ids": ["havana-diani", "funky-monkey"]}, {"label": "The beach rooms", "desc": "Two rooms on the sand for the end of the day: a bar round a baobab and the kite crowd's table.", "ids": ["the-41-beach-club", "salty-squid"]}, {"label": "The old houses", "desc": "Two old addresses with their own history: the crab house on Wasini since 1978, and Tiwi's camp.", "ids": ["charlie-claws", "twiga-lodge"]}]}, "street": {"title": "La Rue — The Street", "desc": "No tables. A machete, a griddle, a charcoal drum — and one rule: only what is cooked in front of you.", "sections": [{"label": "The street", "desc": "No tables at all: a green coconut opened with a panga, the dawn triangles, and palm wine poured in a living room.", "ids": ["madafu-vendors", "mahamri-stalls", "mangwe-dens"]}]}};
  const CATEGORIES = [{"key": "creme", "label": "The famous rooms", "lead": "Three rooms worth a booking and a taxi: the coral cave, the canvas tent on the sand at Galu, and the strip's most complete kitchen.", "story": {"title": "Dinner inside a coral cave", "story": "Ali Barbour's opened in 1983 in a coral cave estimated at 120,000 to 180,000 years old: only the kitchen and the bathrooms were built, and the chambers were left as the sea made them, open to the sky. That is the whole argument of this strip in one room — the best things here were not constructed, they were found, and then somebody put a kitchen next to them. George Barbour died in 2018; the cave he found under the forest keeps serving about seventy covers a night.", "where": "Ali Barbour's Cave, off Diani Beach Road — two seatings, the late one for the stars"}}, {"key": "rising", "label": "The new wave", "lead": "Two kitchens trying something on the beach road: a Japanese family's sushi house and a palm-shaded bistro.", "story": {"title": "New, on an old road", "story": "New on this strip rarely means a concept with a launch. It means a family, or a small hotel, that found a corner of the beach road and decided to cook one thing properly: raw fish from the local landings cut the Japanese way, or a beachfront menu that changes its mood on a Friday night. Neither is a secret, both are booked by residents, and both reward a call ahead, because on this coast the listings disagree about opening days more often than the kitchens change.", "where": "Shashin-Ka on the beach road; Asha's bistro on the sand"}}, {"key": "houses", "label": "The house tables", "lead": "Three houses that cook for people who are not staying, if you ask first: beside the sacred forest, with no meal times, and on the island.", "story": {"title": "Ten hotels, one survivor economy", "story": "Diani's dining rooms are hotel rooms because Diani was built by hotels: ten majors ruled the strip in the 1970s–80s, all but two German-managed. By 2013 only thirteen of twenty remained open, and the 2014–15 travel advisories emptied the coast to 5–15% occupancy. The kitchens that survived learned to cook like private houses — small, flexible, arranged by phone. That is why the best tables here answer to a call, not a queue.", "where": "Kinondo Kwetu, The Maji, Chale Island — always by arrangement"}}, {"key": "landings", "label": "Where the boats land", "lead": "Where the fish and the vegetables come ashore: the landing you can walk to, the channel port, and the new covered market.", "story": {"title": "A fishery with a KSh 256 million future", "story": "Mwaepe is one of seven artisanal landing stations on the Diani–Chale reef, studied by marine scientists since the late 1990s, and in March 2025 the government broke ground here on a modern landing site — ice plant, fish banda, gear shed, boatyard — on land the fishermen already worked. Down the coast the KSh 2.6 billion Shimoni fish port was handed over in July 2025 and then sat awaiting an operator. The infrastructure is arriving faster than the institutions to run it, which is the single most useful thing to understand about buying fish on this coast.", "where": "Mwaepe at 06:00–09:00; Shimoni for the tuna-and-kingfish class"}}, {"key": "swahili", "label": "The Swahili kitchens", "lead": "Ukunda's kitchens, where the strip's staff eat: biryani, nyama choma and pilau at resident prices.", "story": {"title": "The staff canteen of the coast", "story": "Ukunda is where the people who run the strip eat, and its kitchens cook for them: coast biryani with a sour, tangy mchuzi on the side, pilau at Friday lunch when the mosques empty, pweza soup at the grills. Prices are the town's, the rooms are plain, and the first plate of the day is the best one. The dish to judge a kitchen by, and how to say it, is in La liste at the foot.", "where": "Ukunda: Moiz on Hospital Road, Karafuu, Swahili Pot"}}, {"key": "italian", "label": "The Italian residency", "lead": "The Italian residency of the beach road: the wood oven that anchors it, and the neighbour a few doors along.", "story": {"title": "Why the pizza is good here", "story": "Diani's Italian restaurants are not an import laid on for visitors; they are what a community that has lived here for decades cooks for itself. The tell is the pricing and the hours — rooms that fill with the same faces on a Tuesday in low season. When you have eaten grilled reef fish four nights running, this is the answer, and it is a local one.", "where": "Leonardo's and Aniello's, both long-standing on the strip"}}, {"key": "breakfast", "label": "The breakfast tables", "lead": "Coffee and the first meal: the strip's café since 2000, the deaf-staffed café on the sand, and German bread.", "story": {"title": "Three breakfasts, three histories", "story": "The first meal on this strip tells you who settled it. One café has poured the coast's espresso since the turn of the century; one bakes the seed loaves and Berliners of the European families who built the early hotels; one is a Nairobi idea about who gets to work in a café, moved onto the sand at Galu. For the Swahili breakfast itself, the triangles and the pigeon peas, cross the road to Ukunda before eight.", "where": "Kokkos on the strip; Diani Bakehouse beside Apero; Pallet Cafe at Galu"}}, {"key": "grills", "label": "The fire", "lead": "Fish over charcoal at the landing and meat at the junction: the fire where the coast cooks.", "story": {"title": "Where the people who run the strip eat", "story": "From late afternoon the Ukunda–Diani junction fills with charcoal and karai pans: viazi karai in turmeric batter with chilli-tamarind, mishkaki over the coals, grilled corn at about twenty shillings. It sits at the town's transport heart, so this is where the boda riders and shop staff who run the whole strip actually eat. The fire is the cheapest and least performed cooking on this coast.", "where": "The Ukunda junction just after sunset; the fish shacks at Mwaepe by day"}}, {"key": "chefs-eat", "label": "Where the residents eat", "lead": "Where the people who run the strip eat and drink after work: a Belgian bistro, the late kitchen, and the bar team with a ranking.", "story": {"title": "The staff-canteen rule", "story": "On a coast where almost every table is priced for a one-week visitor, the useful question is not where the best food is but where the people who live here go on a Tuesday. They know which kitchen buys off the landing that morning and which one freezes, and which room still has a kitchen open at eleven. Follow them and you will pay roughly half and eat fresher.", "where": "Havana on the strip until late; Funky Monkey once the beach bars wind down"}}, {"key": "beach-rooms", "label": "The beach rooms", "lead": "Two rooms on the sand for the end of the day: a bar round a baobab and the kite crowd's table.", "story": {"title": "A strip that got its evenings back", "story": "For five years muggings emptied Diani Beach Road after dark. In May 2024 the national press reported the change: Kwale County's solar streetlights had brought the nightlife back, and named the venues that reopened behind them. It is worth knowing that this strip's evening economy is about two years old in its current form — which is also why several of its clubs have a press trail and no working channel.", "where": "The 41 and Salty Squid on the sand; the clubs listed under Sundowners"}}, {"key": "story", "label": "The old houses", "lead": "Two old addresses with their own history: the crab house on Wasini since 1978, and Tiwi's camp.", "story": {"title": "1978, and what has gone since", "story": "A short line of houses carries this coast's whole story. Charlie Claw's has fed the Wasini crossing since 1978; Ali Barbour's has served dinner in its cave since 1983; Diving the Crab has worked the reef since 1985. Four Twenty South, on Galu, has traded under one name or another since 1958 — when Ukunda was one duka and a petrol station. Set against that, the hotels that closed in the 2013–15 contraction are the anomaly, not these.", "where": "Charlie Claw's on the Wasini crossing; Twiga Lodge at Tiwi"}}, {"key": "street", "label": "The street", "lead": "No tables at all: a green coconut opened with a panga, the dawn triangles, and palm wine poured in a living room.", "story": {"title": "Before eight or nothing", "story": "The mama stalls at Ukunda fry mahamri from before dawn and the first batches are gone before eight, at thirty to fifty shillings a piece, dipped in mbaazi ya nazi — pigeon peas in coconut — with spiced chai. The same benches turn out biryani and pilau by late morning and whole fried fish after that. No stall names survive verification: it is a pan-and-bench economy, and the way in is to go early and point.", "where": "The mahamri mamas at Ukunda, 06:30–08:00; the madafu vendors all day on the sand"}}];
  const GROUPS = [{"key": "grande", "label": "Les Grandes Tables", "lead": "The rooms worth planning a day around: the coral cave, the canvas on the sand, the new wave, the house tables, and the landings that feed them all."}, {"key": "petite", "label": "Les Petites Tables", "lead": "Ukunda's kitchens, the Italian residency, the breakfast rooms, the fire, where the residents eat, the beach rooms and the old houses — character over ceremony, most of it inland of the sand."}, {"key": "street", "label": "La Rue — The Street", "lead": "No tables at all. A machete and a green coconut, a mama's griddle at dawn, a grill at the junction — the cheapest and often the truest food on this coast."}];
